def download(remote_location, remotes=None, prefix="", dry_run=False):
    """
    Download resources from a stage server.
    """
    if remotes is None:
        remotes = get_remotes()
    if not remote_location.startswith("http"):
        remote_location = "http://" + remote_location
    if not remote_location.endswith("/"):
        remote_location += "/"
    for remote in remotes:
        if remote_location.startswith(remote):
            local_location = remote_location.replace(remote, prefix)
            if not local_location.endswith("/"):
                local_location += "/"
            if not dry_run:
                os.makedirs(os.path.dirname(local_location), exist_ok=True)
                if not os.path.exists(local_location):
                    print("Downloading %s" % remote_location)
                    urllib.request.urlretrieve(remote_location, local_location)

