def get_remotes():
    """
    Get the list of remote locations.
    """
    remotes = []
    for line in open("remotes"):
        line = line.strip()
        if line and not line.startswith("#"):
            remotes.append(line)
    return remotes


def get_remote_location():
    """
    Get the remote location.
    """
    for line in open("remotes"):
        line = line.strip()
        if line and not line.startswith("#") and line.startswith("http"):
            return line


